function calculatePensionTransfer() {
            const amount = parseFloat(document.getElementById('transferAmount').value);

            if (isNaN(amount) || amount <= 0) {
                alert('정확한 이전 금액을 입력해 주세요.');
                return;
            }

            const finalCreditLimit = Math.min(amount * 0.1, 3000000);

            document.getElementById('creditLimit').textContent = Math.floor(finalCreditLimit).toLocaleString();
            document.getElementById('transferResultBox').style.display = 'block';
        }

